function interpretarContacto(respuesta, ghl) {
  const r = respuesta || {};
  const resultado = ghl.interpretarUpsertContacto(r.statusCode, r.body);
  return resultado.ok
    ? { ghl_contact_id: resultado.ghl_contact_id, error: null }
    : { ghl_contact_id: null, error: resultado };
