  planificarAgenda,
  solicitudContacto,
  interpretarContacto,
  solicitudHorarios,
  interpretarHorarios,
  solicitudReserva,
  interpretarReserva,
  solicitudNota,
  solicitudCitasPrevias,
  citaYaCreada,
  interpretarNota,
};
